<?php
/**
 * Prom.ua recommended category attributes.
 *
 * The list is published by Prom in the help article "Характеристики товарів"
 * as recommended-attributes.xlsx. A compact copy lives in
 * data/prom-recommended-attributes.tsv and is regenerated by
 * bin/update-prom-recommended-attributes.py.
 *
 * The mapping is "Prom category + Prom characteristic => a site attribute".
 * The feed only needs the characteristic name and the site attribute label;
 * values still come from the product.
 *
 * @package Factorial2000_Catalog_Sync
 */

namespace F2000CS;

defined( 'ABSPATH' ) || exit;

/**
 * Recommended attributes and their site-attribute mapping.
 */
class Prom_Recommendations {

	/**
	 * Read categories per request.
	 *
	 * @var array<string, array>|null
	 */
	private static $data = null;

	/**
	 * Site attributes per request.
	 *
	 * @var array<string, array>|null
	 */
	private static $site_attributes = null;

	/**
	 * Parsed mappings by stored JSON per request.
	 *
	 * @var array<string, array>
	 */
	private static $maps = array();

	/**
	 * File with the recommended attributes.
	 *
	 * @return string
	 */
	public static function file(): string {
		/**
		 * Filters the file with Prom's recommended attributes.
		 *
		 * @param string $file Absolute path.
		 */
		return (string) apply_filters( 'f2000cs_prom_recommended_attributes_file', __DIR__ . '/data/prom-recommended-attributes.tsv' );
	}

	/**
	 * All recommended categories: id => row.
	 *
	 * @return array<string, array{id:string,name_uk:string,attrs_uk:array<int,string>,name_ru:string,attrs_ru:array<int,string>}>
	 */
	public static function all(): array {
		if ( null !== self::$data ) {
			return self::$data;
		}

		self::$data = array();
		$file       = self::file();

		if ( ! is_readable( $file ) ) {
			return self::$data;
		}

		// phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_file -- Bundled read-only data file.
		foreach ( (array) file( $file, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES ) as $line ) {
			if ( '' === $line || '#' === $line[0] ) {
				continue;
			}

			$parts = explode( "\t", $line );

			if ( count( $parts ) < 5 || ! ctype_digit( $parts[0] ) ) {
				continue;
			}

			self::$data[ $parts[0] ] = array(
				'id'       => $parts[0],
				'name_uk'  => trim( $parts[1] ),
				'attrs_uk' => self::split_attrs( $parts[2] ),
				'name_ru'  => trim( $parts[3] ),
				'attrs_ru' => self::split_attrs( $parts[4] ),
			);
		}

		return self::$data;
	}

	/**
	 * Forget the loaded data and site attributes (tests, or a changed file).
	 *
	 * @return void
	 */
	public static function reset(): void {
		self::$data            = null;
		self::$site_attributes = null;
		self::$maps            = array();
	}

	/**
	 * One category from the recommended list.
	 *
	 * @param string|int $id Category id.
	 * @return array|null
	 */
	public static function category( $id ) {
		$id = Prom_Categories::sanitize_id( $id );

		return '' !== $id && isset( self::all()[ $id ] ) ? self::all()[ $id ] : null;
	}

	/**
	 * Selected categories with their recommended characteristics.
	 *
	 * @param array<int,string|int> $ids Prom category ids.
	 * @return array<string, array{id:string,path:string,name_uk:string,name_ru:string,attrs:array<int,array{name:string,name_ru:string,key:string}>}>
	 */
	public static function categories( array $ids ): array {
		$out = array();

		foreach ( $ids as $id ) {
			$id = Prom_Categories::sanitize_id( $id );

			if ( '' === $id || isset( $out[ $id ] ) ) {
				continue;
			}

			$row  = self::category( $id );
			$path = Prom_Categories::path( $id );

			$out[ $id ] = array(
				'id'      => $id,
				'path'    => '' !== $path ? $path : ( $row ? $row['name_uk'] : '#' . $id ),
				'name_uk' => $row ? $row['name_uk'] : '',
				'name_ru' => $row ? $row['name_ru'] : '',
				'attrs'   => $row ? self::attrs_for_row( $row ) : array(),
			);
		}

		uasort(
			$out,
			static function ( $a, $b ) {
				return strcmp( Marketplace_Text::lower( $a['path'] ), Marketplace_Text::lower( $b['path'] ) );
			}
		);

		return $out;
	}

	/**
	 * Unique recommended characteristics across categories.
	 *
	 * @param array<string, array> $categories Result of categories().
	 * @return array<string, array{name:string,name_ru:string,categories:array<string,string>}>
	 */
	public static function unique_attributes( array $categories ): array {
		$out = array();

		foreach ( $categories as $category ) {
			foreach ( (array) $category['attrs'] as $attr ) {
				$key = $attr['key'];

				if ( '' === $key ) {
					continue;
				}

				if ( ! isset( $out[ $key ] ) ) {
					$out[ $key ] = array(
						'name'       => $attr['name'],
						'name_ru'    => $attr['name_ru'],
						'categories' => array(),
					);
				}

				$out[ $key ]['categories'][ $category['id'] ] = $category['path'];
			}
		}

		uasort(
			$out,
			static function ( $a, $b ) {
				return strcmp( Marketplace_Text::lower( $a['name'] ), Marketplace_Text::lower( $b['name'] ) );
			}
		);

		return $out;
	}

	/**
	 * Site attributes that can be mapped: global WooCommerce taxonomies.
	 *
	 * A custom attribute can be typed in the Select2 (tags) or added with the
	 * f2000cs_prom_site_attributes filter.
	 *
	 * @return array<string, array{key:string,label:string,source:string,type:string}>
	 */
	public static function site_attributes(): array {
		if ( null !== self::$site_attributes ) {
			return self::$site_attributes;
		}

		$out = array();

		if ( function_exists( 'wc_get_attribute_taxonomies' ) ) {
			foreach ( (array) wc_get_attribute_taxonomies() as $tax ) {
				if ( ! is_object( $tax ) || empty( $tax->attribute_name ) ) {
					continue;
				}

				$name  = (string) $tax->attribute_name;
				$label = isset( $tax->attribute_label ) ? trim( (string) $tax->attribute_label ) : '';
				$key   = 'pa_' . $name;

				$out[ $key ] = array(
					'key'    => $key,
					'label'  => '' !== $label ? $label : $name,
					'source' => 'global',
					'type'   => isset( $tax->attribute_type ) ? (string) $tax->attribute_type : 'select',
				);
			}
		}

		/**
		 * Filter the site attributes available for the Prom mapping.
		 *
		 * @param array<string, array{key:string,label:string,source:string,type:string}> $attributes Attributes.
		 */
		$filtered = apply_filters( 'f2000cs_prom_site_attributes', $out );

		if ( is_array( $filtered ) ) {
			$out = array();

			foreach ( $filtered as $key => $attr ) {
				if ( ! is_array( $attr ) ) {
					continue;
				}

				$out[ (string) $key ] = array(
					'key'    => (string) $key,
					'label'  => isset( $attr['label'] ) ? (string) $attr['label'] : (string) $key,
					'source' => isset( $attr['source'] ) ? (string) $attr['source'] : 'custom',
					'type'   => isset( $attr['type'] ) ? (string) $attr['type'] : 'select',
				);
			}
		}

		uasort(
			$out,
			static function ( $a, $b ) {
				return strcmp( Marketplace_Text::lower( (string) $a['label'] ), Marketplace_Text::lower( (string) $b['label'] ) );
			}
		);

		self::$site_attributes = $out;

		return $out;
	}

	/**
	 * Label of a mapped site attribute.
	 *
	 * @param string     $key     Site attribute key.
	 * @param array|null $attributes Site attributes.
	 * @return string
	 */
	public static function site_label( $key, $attributes = null ): string {
		$key  = (string) $key;
		$list = null === $attributes ? self::site_attributes() : $attributes;

		if ( isset( $list[ $key ]['label'] ) ) {
			return (string) $list[ $key ]['label'];
		}

		if ( 0 === strpos( $key, 'custom:' ) ) {
			return substr( $key, 7 );
		}

		if ( 0 === strpos( $key, 'pa_' ) ) {
			if ( function_exists( 'wc_attribute_label' ) ) {
				return (string) wc_attribute_label( $key );
			}

			return ucfirst( str_replace( '_', ' ', substr( $key, 3 ) ) );
		}

		return $key;
	}

	/**
	 * Normalize an attribute name for exact matching.
	 *
	 * Lower case, no apostrophes, ё -> е, only letters and digits left.
	 *
	 * @param mixed $name Name.
	 * @return string
	 */
	public static function normalize( $name ): string {
		$name = Marketplace_Text::lower( Marketplace_Text::clean( $name ) );
		$name = str_replace( array( 'ё', '’', '`', "'" ), array( 'е', '', '', '' ), $name );
		$name = preg_replace( '/[^\p{L}\p{N}]+/u', '', $name );

		return is_string( $name ) ? $name : '';
	}

	/**
	 * Auto-match a Prom characteristic to a site attribute by name.
	 *
	 * @param string $name    Prom name (Ukrainian).
	 * @param string $name_ru Prom name (Russian).
	 * @param array  $attributes Site attributes.
	 * @return string Site key or ''.
	 */
	public static function match( $name, $name_ru = '', $attributes = null ): string {
		$list = null === $attributes ? self::site_attributes() : $attributes;
		$by   = array();

		foreach ( $list as $key => $attr ) {
			$norm = self::normalize( $attr['label'] ?? '' );

			if ( '' === $norm ) {
				continue;
			}

			if ( ! isset( $by[ $norm ] ) || ( 'global' === $attr['source'] && 'global' !== $by[ $norm ]['source'] ) ) {
				$by[ $norm ] = array(
					'key'    => (string) $key,
					'source' => (string) ( $attr['source'] ?? '' ),
				);
			}
		}

		foreach ( array( $name, $name_ru ) as $candidate ) {
			$norm = self::normalize( $candidate );

			if ( '' !== $norm && isset( $by[ $norm ] ) ) {
				return $by[ $norm ]['key'];
			}
		}

		return '';
	}

	/**
	 * Mapping from the stored setting.
	 *
	 * @param array<string,mixed> $settings Feed settings.
	 * @return array<string, array<string, string>>
	 */
	public static function map_from_settings( array $settings ): array {
		$raw = $settings['prom_attribute_map'] ?? '';

		if ( is_string( $raw ) ) {
			if ( isset( self::$maps[ $raw ] ) ) {
				return self::$maps[ $raw ];
			}

			self::$maps[ $raw ] = self::sanitize_map_array( $raw );

			return self::$maps[ $raw ];
		}

		return self::sanitize_map_array( $raw );
	}

	/**
	 * Sanitize a mapping and store it as JSON.
	 *
	 * @param mixed $raw JSON string or array.
	 * @return string
	 */
	public static function sanitize_json( $raw ): string {
		$map = self::sanitize_map_array( $raw );

		if ( array() === $map ) {
			return '';
		}

		// phpcs:ignore WordPress.WP.AlternativeFunctions.json_encode_json_encode -- Fallback for unit tests without wp_json_encode().
		$json = function_exists( 'wp_json_encode' ) ? wp_json_encode( $map, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES ) : json_encode( $map, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES );

		return is_string( $json ) ? $json : '';
	}

	/**
	 * Sanitize a mapping to [category][prom name] = site key.
	 *
	 * @param mixed $raw JSON string or array.
	 * @return array<string, array<string, string>>
	 */
	public static function sanitize_map_array( $raw ): array {
		if ( is_string( $raw ) ) {
			$raw = trim( $raw );
			$raw = '' === $raw ? array() : json_decode( $raw, true );
		}

		if ( ! is_array( $raw ) ) {
			return array();
		}

		$out = array();

		foreach ( $raw as $category_id => $attributes ) {
			$category_id = Prom_Categories::sanitize_id( $category_id );

			if ( '' === $category_id || ! is_array( $attributes ) ) {
				continue;
			}

			foreach ( $attributes as $prom_name => $site_key ) {
				$prom_name = Marketplace_Text::clean( (string) $prom_name );
				$site_key  = Marketplace_Text::clean( (string) $site_key );

				if ( '' !== $prom_name && '' !== $site_key ) {
					$out[ $category_id ][ $prom_name ] = $site_key;
				}
			}
		}

		return $out;
	}

	/**
	 * Apply a category mapping to Prom <param> pairs.
	 *
	 * A mapped site attribute is replaced by the Prom characteristic name. A
	 * site attribute without a mapping stays in the feed as a custom
	 * characteristic. If several Prom names point at one site attribute, the
	 * value is repeated under each name.
	 *
	 * @param array<int, array{0:string,1:string}> $params   Name/value pairs.
	 * @param string                               $portal   Prom category id.
	 * @param array<string,mixed>                  $settings Feed settings.
	 * @return array<int, array{0:string,1:string}>
	 */
	public static function apply_params( array $params, $portal, array $settings ): array {
		$portal = Prom_Categories::sanitize_id( $portal );
		$map    = self::map_from_settings( $settings );

		if ( '' === $portal || empty( $map[ $portal ] ) ) {
			return $params;
		}

		$site    = self::site_attributes();
		$targets = array();

		foreach ( $map[ $portal ] as $prom_name => $site_key ) {
			$label = self::site_label( $site_key, $site );
			$norm  = self::normalize( $label );

			if ( '' !== $norm ) {
				$targets[ $norm ][] = (string) $prom_name;
			}
		}

		if ( array() === $targets ) {
			return $params;
		}

		$out  = array();
		$seen = array();

		foreach ( $params as $pair ) {
			if ( ! is_array( $pair ) || count( $pair ) < 2 ) {
				continue;
			}

			$site_name = (string) $pair[0];
			$value     = (string) $pair[1];
			$norm      = self::normalize( $site_name );

			if ( isset( $targets[ $norm ] ) ) {
				foreach ( $targets[ $norm ] as $prom_name ) {
					$key = Marketplace_Text::lower( $prom_name ) . "\x1f" . Marketplace_Text::lower( $value );

					if ( ! isset( $seen[ $key ] ) ) {
						$seen[ $key ] = true;
						$out[]        = array( $prom_name, $value );
					}
				}

				continue;
			}

			$key = Marketplace_Text::lower( $site_name ) . "\x1f" . Marketplace_Text::lower( $value );

			if ( ! isset( $seen[ $key ] ) ) {
				$seen[ $key ] = true;
				$out[]        = $pair;
			}
		}

		return $out;
	}

	/**
	 * Attributes of one xlsx row with both languages.
	 *
	 * @param array $row Data row.
	 * @return array<int, array{name:string,name_ru:string,key:string}>
	 */
	private static function attrs_for_row( array $row ): array {
		$uk    = (array) ( $row['attrs_uk'] ?? array() );
		$ru    = (array) ( $row['attrs_ru'] ?? array() );
		$out   = array();
		$seen  = array();
		$count = max( count( $uk ), count( $ru ) );

		for ( $i = 0; $i < $count; $i++ ) {
			$name    = trim( (string) ( $uk[ $i ] ?? $ru[ $i ] ?? '' ) );
			$name_ru = trim( (string) ( $ru[ $i ] ?? $uk[ $i ] ?? '' ) );

			if ( '' === $name ) {
				continue;
			}

			$key = self::normalize( $name );

			if ( '' === $key || isset( $seen[ $key ] ) ) {
				continue;
			}

			$seen[ $key ] = true;
			$out[]        = array(
				'name'    => $name,
				'name_ru' => $name_ru,
				'key'     => $key,
			);
		}

		return $out;
	}

	/**
	 * Split a pipe-separated attribute list.
	 *
	 * @param string $value Value.
	 * @return array<int,string>
	 */
	private static function split_attrs( $value ): array {
		return array_values(
			array_filter(
				array_map( 'trim', explode( '|', (string) $value ) ),
				static function ( $item ) {
					return '' !== $item;
				}
			)
		);
	}
}
